using System.Net;
using System.Text;
using System.Text.Json;
using System.Text.Json.Nodes;

public static class WarrantyPages
{
    static string E(string? value) => WebUtility.HtmlEncode(value ?? "");

    public static string Public(JsonObject catalog)
    {
        var s = catalog["settings"]!.AsObject();
        var name = s["name"]?.ToString() ?? "İNOKSKAR";
        var tagline = s["tagline"]?.ToString() ?? "";
        var headerImage = s["headerImage"]?.ToString() ?? "/inokskar-header-brand.png";
        var nav = new StringBuilder();
        foreach (var c in catalog["categories"]!.AsArray().Where(x => x?["menu"]?.GetValue<bool>() == true))
            nav.Append($"<a href='/kategori/{Uri.EscapeDataString(c!["id"]!.ToString())}'>{E(c["name"]?.ToString())}</a>");
        foreach (var m in s["menu"]!.AsArray().Where(x => x?["url"]?.ToString() != "/blog" && x?["url"]?.ToString() != "/garanti-sorgulama" && x?["url"]?.ToString() != "/servis-talebi"))
            nav.Append($"<a href='{E(m!["url"]?.ToString())}'>{E(m["name"]?.ToString())}</a>");
        nav.Append("<a class='active' href='/garanti-sorgulama'>Garanti Sorgula</a><a href='/servis-talebi'>Servis Talebi</a>");
        var html = """
<!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="theme-color" content="#252b33"><meta name="mobile-web-app-capable" content="yes"><meta name="apple-mobile-web-app-capable" content="yes"><meta name="apple-mobile-web-app-status-bar-style" content="black-translucent"><meta name="apple-mobile-web-app-title" content="İNOKSKAR"><title>Garanti Sorgulama | @@NAME@@</title><meta name="description" content="İnokskar ürününüzün garanti durumunu seri numarası ve doğrulama koduyla güvenli şekilde sorgulayın."><link rel="stylesheet" href="/r95-warranty.css"><link rel="stylesheet" href="/r99-brand.css"><link rel="stylesheet" href="/r103-public.css"><link rel="stylesheet" href="/r123-professional.css"><script src="/r123-security.js" defer></script><link rel="stylesheet" href="/r13-interface.css"><link rel="stylesheet" href="/r13-pages.css?v=r21-1"><script src="/r13-pages.js?v=r21-1" defer></script></head><body class="warranty-public-body">
<header class="site-header"><a class="brand brand-image-link" href="/"><img class="header-brand-image" src="@@HEADER_IMAGE@@" alt="@@NAME@@ @@TAGLINE@@"></a><nav class="main-nav warranty-nav">@@NAV@@</nav><div class="header-actions"><a class="small-btn" href="/urunler">Ürünler</a></div></header>
<div class="public-home-return-wrap"><a class="public-home-return" href="/">← Ana sayfaya dön</a></div>
<main class="warranty-page"><section class="warranty-intro wrap"><p class="eyebrow">İNOKSKAR SATIŞ SONRASI HİZMETLER</p><h1>Garanti &amp; Servis Merkezi</h1><p>Ürününüzün garanti kaydını iki aşamalı doğrulama ile kontrol edin. Seri numarası ve garanti doğrulama kodu birlikte gereklidir.</p></section>
<section class="wrap warranty-layout"><div class="warranty-query-card"><div class="warranty-query-head"><span class="warranty-shield">✓</span><div><h2>Garanti kaydınızı doğrulayın</h2><p>Her iki bilgiyi ürününüzün garanti belgesinde yer aldığı şekilde girin.</p></div></div><form id="warranty-query-form" class="warranty-form"><label>Seri Numarası<input name="serialNumber" maxlength="100" autocomplete="off" required placeholder="Seri numaranızı girin"></label><label>Garanti Doğrulama Kodu<input name="verificationCode" maxlength="32" autocomplete="off" required placeholder="Örn. K7P4M-9X2QD"></label><button class="button" type="submit">Garantiyi sorgula</button><p class="warranty-privacy">Güvenlik için yalnız seri numarası yeterli değildir. Yanlış girişlerde hangi bilginin hatalı olduğu açıklanmaz.</p></form></div><div id="warranty-result" class="warranty-result" aria-live="polite"><div class="warranty-placeholder"><strong>Garanti bilgileri burada görüntülenecek.</strong><span>Teslim tarihi, bitiş tarihi, kalan gün ve bileşen bazlı kapsam tek ekranda gösterilir.</span></div></div></section></main>
<script src="/r95-warranty-query.js" defer></script></body></html>
""";
        return html
            .Replace("@@NAME@@", E(name), StringComparison.Ordinal)
            .Replace("@@TAGLINE@@", E(tagline), StringComparison.Ordinal)
            .Replace("@@HEADER_IMAGE@@", E(headerImage), StringComparison.Ordinal)
            .Replace("@@NAV@@", nav.ToString(), StringComparison.Ordinal)
            .Replace("@@YEAR@@", DateTime.Now.Year.ToString(), StringComparison.Ordinal);
    }

    public static string Admin() => """
