    public static string Certificate(JsonObject warranty)
    {
        var components = new StringBuilder();
        foreach (var node in warranty["components"]?.AsArray() ?? new JsonArray())
        {
            var c = node?.AsObject();
            if (c == null) continue;
            var covered = c["covered"]?.GetValue<bool>() == true;
            components.Append($"<tr><td>{E(c["name"]?.ToString())}</td><td>{(covered ? "Garanti kapsamında" : "Garanti kapsamı dışında")}</td><td>{(covered ? E(c["months"]?.ToString()) + " ay" : "—")}</td><td>{E(c["note"]?.ToString())}</td></tr>");
        }

        var html = """
<!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><title>Garanti Belgesi | İnokskar</title><style>body{font-family:Arial,sans-serif;color:#102a51;margin:0;background:#eef3f8}.page{width:min(900px,calc(100% - 40px));margin:30px auto;background:white;padding:38px;border:1px solid #d9e3ef;border-radius:14px}h1{margin:0 0 6px}.meta{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin:26px 0}.meta div{border:1px solid #e1e8f1;border-radius:9px;padding:12px}.meta span{display:block;font-size:12px;color:#6a7d94;margin-bottom:5px}table{width:100%;border-collapse:collapse;margin-top:22px}th,td{border:1px solid #dfe6ef;padding:10px;text-align:left;font-size:14px}th{background:#f3f6fb}.actions{margin-top:24px;display:flex;gap:10px}button,a{position:relative;overflow:hidden;display:inline-flex;align-items:center;justify-content:center;padding:10px 14px;border-radius:8px;border:0;background:linear-gradient(180deg,#2478df,#1557b8);color:white;text-decoration:none;font-weight:700}button:after,a:after{content:"";position:absolute;top:-90%;bottom:-90%;left:-58%;width:28%;transform:skewX(-22deg);background:linear-gradient(90deg,transparent,#ffffff24,#ffffffd0,#ffffff24,transparent);transition:left .65s ease}button:hover:after,a:hover:after{left:138%}@media(max-width:620px){.page{width:calc(100% - 20px);margin:10px auto;padding:18px 14px;border-radius:12px}.meta{grid-template-columns:1fr 1fr;gap:8px;margin:18px 0}.meta div{padding:10px}.meta strong{overflow-wrap:anywhere}table,tbody,tr,td{display:block;width:100%}thead{display:none}table{border:0;margin-top:16px}tbody{display:grid;gap:10px}tr{border:1px solid #dfe6ef;border-radius:10px;overflow:hidden;background:#fff}td{display:grid;grid-template-columns:minmax(92px,.75fr) minmax(0,1.25fr);gap:10px;border:0;border-bottom:1px solid #edf1f5;padding:9px 10px;font-size:13px;overflow-wrap:anywhere}td:last-child{border-bottom:0}td:before{font-size:11px;font-weight:800;color:#6a7d94;text-transform:uppercase;letter-spacing:.03em}td:nth-child(1):before{content:"Bileşen"}td:nth-child(2):before{content:"Durum"}td:nth-child(3):before{content:"Süre"}td:nth-child(4):before{content:"Açıklama"}.actions{display:grid;grid-template-columns:1fr 1fr;gap:8px}.actions>*{width:100%;min-height:46px;text-align:center}}@media(max-width:390px){.meta{grid-template-columns:1fr}.actions{grid-template-columns:1fr}}@media print{body{background:white}.page{border:0;margin:0;width:100%;padding:0}.actions{display:none}table{display:table}thead{display:table-header-group}tbody{display:table-row-group}tr{display:table-row;border:0}th,td{display:table-cell}td:before{display:none}}</style><link rel="stylesheet" href="/r123-professional.css"><script src="/r123-security.js" defer></script><link rel="stylesheet" href="/r13-interface.css"><link rel="stylesheet" href="/r13-pages.css?v=r21-1"><script src="/r13-pages.js?v=r21-1" defer></script></head><body><main class="page"><p>İNOKSKAR SOĞUTMA VE ENDÜSTRİYEL MUTFAK</p><h1>Garanti Belgesi</h1><p>Bu belge yönetim sistemindeki garanti kaydından oluşturulmuştur.</p><section class="meta"><div><span>İşletme</span><strong>@@BUSINESS@@</strong></div><div><span>Ürün</span><strong>@@PRODUCT@@</strong></div><div><span>Ürün Kodu</span><strong>@@PRODUCT_CODE@@</strong></div><div><span>Seri Numarası</span><strong>@@SERIAL@@</strong></div><div><span>Teslim Tarihi</span><strong>@@DELIVERY@@</strong></div><div><span>Garanti Bitiş Tarihi</span><strong>@@END@@</strong></div><div><span>Garanti Süresi</span><strong>@@MONTHS@@ ay</strong></div><div><span>Doğrulama Kodu</span><strong>@@CODE@@</strong></div></section><p><strong>Fatura No:</strong> @@INVOICE@@</p><p><strong>Teslim Belgesi No:</strong> @@DELIVERY_DOC@@</p><p><strong>Not:</strong> @@NOTE@@</p><h2>Garanti kapsamı</h2><table><thead><tr><th>Bileşen</th><th>Durum</th><th>Süre</th><th>Açıklama</th></tr></thead><tbody>@@COMPONENTS@@</tbody></table><div class="actions"><button type="button" onclick="window.print()">Yazdır / PDF olarak kaydet</button><a href="/admin/warranties/list">Listeye dön</a></div></main></body></html>
""";
        return html
            .Replace("@@BUSINESS@@", E(warranty["businessName"]?.ToString()), StringComparison.Ordinal)
            .Replace("@@PRODUCT@@", E(warranty["productName"]?.ToString()), StringComparison.Ordinal)
            .Replace("@@PRODUCT_CODE@@", E(warranty["productCode"]?.ToString()), StringComparison.Ordinal)
            .Replace("@@SERIAL@@", E(warranty["serialNumber"]?.ToString()), StringComparison.Ordinal)
            .Replace("@@DELIVERY@@", E(warranty["deliveryDate"]?.ToString()), StringComparison.Ordinal)
            .Replace("@@END@@", E(warranty["warrantyEndDate"]?.ToString()), StringComparison.Ordinal)
            .Replace("@@MONTHS@@", E(warranty["warrantyMonths"]?.ToString()), StringComparison.Ordinal)
            .Replace("@@CODE@@", E(warranty["verificationCode"]?.ToString()), StringComparison.Ordinal)
            .Replace("@@INVOICE@@", E(warranty["invoiceNumber"]?.ToString()), StringComparison.Ordinal)
            .Replace("@@DELIVERY_DOC@@", E(warranty["deliveryDocumentNumber"]?.ToString()), StringComparison.Ordinal)
            .Replace("@@NOTE@@", E(warranty["warrantyNote"]?.ToString()), StringComparison.Ordinal)
            .Replace("@@COMPONENTS@@", components.ToString(), StringComparison.Ordinal);
    }

}
